package com.skyclone.mod.shops;

import com.google.gson.Gson;
import com.google.gson.reflect.TypeToken;

import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.Reader;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.List;

/**
 * The shape of {@code data/shops/shops.json} and {@code townsfolk.json} (generated by
 * {@code tools/gen/shops/gen_shops.py}). Pure: no Bukkit, so the unit tests load the shipped files.
 */
public final class ShopData {

    private ShopData() {}

    /** One merchant. */
    public static final class Shop {
        public String id;
        /** '&' coded NPC / menu name, already renamed. */
        public String name;
        public String island;
        public String anchor;
        /** "contract" (anchor guaranteed by CONTRACT §4) or "secondary" (anchor requested, may be missing). */
        public String mode;
        public String category;
        /** Material name used as the directory icon. */
        public String icon;
        /** Where the merchant is meant to stand, in words (for secondary merchants without an anchor yet). */
        public String where;
        public String skin;
        public List<String> greeting = new ArrayList<>();
        public List<String> source = new ArrayList<>();
        public String refIsland;
        public List<Group> groups = new ArrayList<>();
        public List<Entry> entries = new ArrayList<>();
        /**
         * Requirement key (see {@code api.util.Requirements}) a player must meet to BUY anything here, or null. The
         * faction envoys of the crimson isle trade only with their own faction. Selling is never gated.
         */
        public String req;
        /**
         * Hunting attribute whose value is an extra percent off this merchant's coin prices ("builder_discount" for
         * the Builder, "bartender_discount" for the Bartender: shards Woodchucker / Bloodbat), or null.
         * Read through {@code Features.Hunting.attributeLevel(p, "value:" + discountAttr)} (wave 5).
         */
        public String discountAttr;
        /**
         * Crimson faction whose reputation discounts this merchant's {@code emissary} lines (the envoys are the
         * reference's Emissaries; audit 2026-10-06 K17 follow-up), or null.
         */
        public String emissaryFaction;

        public boolean contract() { return "contract".equals(mode); }

        public Group group(String gid) {
            if (groups == null) return null;
            for (Group g : groups) if (g.id.equals(gid)) return g;
            return null;
        }
    }

    /** Category tab inside a big shop (Builder, Wool Weaver). */
    public static final class Group {
        public String id;
        public String name;
        public String icon;
    }

    /** One line of stock: {@code amount} of {@code item} for the listed costs. */
    public static final class Entry {
        /** Primary item id. "@MATERIAL" = core's sky id for that vanilla material. */
        public String item;
        /** Alternative ids tried in order when the primary is not registered. */
        public List<String> alts = new ArrayList<>();
        public int amount = 1;
        public double coins;
        public long bits;
        public List<ItemCost> items = new ArrayList<>();
        public List<CurrencyCost> currency = new ArrayList<>();
        public String group;
        /** Price is our design (the research has no number for it). */
        public boolean tune;
        /** Requirement key for this line on top of the shop's own ({@code faction:mage:3000}), or null. */
        public String req;
        /** Why a number differs from the neu-repo snapshot (shown by /sb shops info), or null. */
        public String note;
        /** A Leviathan key line: its coin price drops with {@link Shop#emissaryFaction} reputation (dial shops.emissary-discount). */
        public boolean emissary;

        public boolean hasItemCosts() { return items != null && !items.isEmpty(); }
        public boolean hasCurrency() { return currency != null && !currency.isEmpty(); }
        public boolean coinsOnly() { return bits == 0 && !hasItemCosts() && !hasCurrency(); }
    }

    public static final class ItemCost {
        public String item;
        public List<String> alts = new ArrayList<>();
        public int amount = 1;
    }

    /** A currency other than coins/bits ("pelt", "north_star", "copper"...): its owner must expose it. */
    public static final class CurrencyCost {
        public String id;
        public long amount;
    }

    /**
     * A merchant another module runs with its own menu (the Community Shop is the bank's, the medal exchange is
     * farming's...). Listed in the Merchant Directory so it really holds every merchant; a click runs the owner's
     * player command, and only when that command is registered ({@code data/shops/external.json}).
     */
    public static final class External {
        public String id;
        public String name;
        public String island;
        public String category;
        public String icon;
        /** The owner's player command (no slash) and its arguments. Never player text. */
        public String command;
        public List<String> args = new ArrayList<>();
        /** Module that runs it (for /sb shops list). */
        public String owner;
        /** Where it stands / what it is, one line in our words. */
        public String about;
    }

    /** A talk-only hub NPC. */
    public static final class Townsfolk {
        public String id;
        public String name;
        public String island;
        public String anchor;
        public String skin;
        public List<String> lines = new ArrayList<>();
    }

    /**
     * The requirement keys a line needs, shop's first: "faction:mage" + "faction:mage:3000". Keys joined with '&'
     * are split (that is how {@code Requirements} spells "all of these"); blanks dropped, duplicates kept once.
     */
    public static List<String> requirementKeys(String shopReq, String entryReq) {
        java.util.LinkedHashSet<String> out = new java.util.LinkedHashSet<>();
        for (String r : new String[]{shopReq, entryReq}) {
            if (r == null) continue;
            for (String part : r.split("&")) if (!part.isBlank()) out.add(part.trim());
        }
        return new ArrayList<>(out);
    }

    /** {@link #requirementKeys} joined back into one key, or null when there is nothing to meet. */
    public static String requirement(String shopReq, String entryReq) {
        List<String> k = requirementKeys(shopReq, entryReq);
        return k.isEmpty() ? null : String.join("&", k);
    }

    private static boolean wellFormedReq(String r) {
        if (r == null) return true;
        for (String part : r.split("&")) if (!part.trim().matches("[a-z_]+(:[A-Za-z0-9_;.-]+)*")) return false;
        return !r.isBlank();
    }

    private static final Gson GSON = new Gson();

    public static List<Shop> readShops(InputStream in) {
        if (in == null) return new ArrayList<>();
        try (Reader r = new InputStreamReader(in, StandardCharsets.UTF_8)) {
            List<Shop> l = GSON.fromJson(r, new TypeToken<List<Shop>>() {}.getType());
            return l == null ? new ArrayList<>() : l;
        } catch (Exception e) {
            throw new IllegalStateException("shops.json unreadable: " + e.getMessage(), e);
        }
    }

    public static List<External> readExternal(InputStream in) {
        if (in == null) return new ArrayList<>();
        try (Reader r = new InputStreamReader(in, StandardCharsets.UTF_8)) {
            List<External> l = GSON.fromJson(r, new TypeToken<List<External>>() {}.getType());
            return l == null ? new ArrayList<>() : l;
        } catch (Exception e) {
            throw new IllegalStateException("external.json unreadable: " + e.getMessage(), e);
        }
    }

    /** Structural problems in the external merchant list (unique ids, a command that is a bare word). */
    public static List<String> validateExternal(List<External> ext, java.util.Set<String> shopIds) {
        List<String> bad = new ArrayList<>();
        java.util.Set<String> ids = new java.util.HashSet<>();
        for (External x : ext) {
            if (x.id == null || !x.id.matches("[a-z0-9_]+")) bad.add("bad external id " + x.id);
            else if (!ids.add(x.id) || (shopIds != null && shopIds.contains(x.id))) bad.add("duplicate external id " + x.id);
            if (x.name == null || x.name.isBlank()) bad.add(x.id + ": no name");
            if (x.command == null || !x.command.matches("[a-z0-9_]+")) bad.add(x.id + ": bad command '" + x.command + "'");
            if (x.args != null) for (String a : x.args) if (a == null || !a.matches("[A-Za-z0-9_:.-]+")) bad.add(x.id + ": bad arg '" + a + "'");
            if (x.island == null || x.island.isBlank()) bad.add(x.id + ": no island");
        }
        return bad;
    }

    public static List<Townsfolk> readTownsfolk(InputStream in) {
        if (in == null) return new ArrayList<>();
        try (Reader r = new InputStreamReader(in, StandardCharsets.UTF_8)) {
            List<Townsfolk> l = GSON.fromJson(r, new TypeToken<List<Townsfolk>>() {}.getType());
            return l == null ? new ArrayList<>() : l;
        } catch (Exception e) {
            throw new IllegalStateException("townsfolk.json unreadable: " + e.getMessage(), e);
        }
    }

    /**
     * "&9Enchanted Book (Sharpness I)": an item name with what tells it apart from its siblings. Every enchanted
     * book level is named just "Enchanted Book" (the enchant is in the lore), so a shop of books is otherwise a
     * column of identical titles. {@code variant} null or blank leaves the name alone.
     */
    public static String withVariant(String name, String variant) {
        if (variant == null || variant.isBlank()) return name;
        return (name == null ? "" : name) + " (" + variant.trim() + ")";
    }

    /** "Sharpness I" - an enchant's name and level as the books read it. */
    public static String enchantLabel(String enchantName, int level) {
        String n = enchantName == null ? "" : enchantName.trim();
        return level <= 0 ? n : (n + " " + roman(level)).trim();
    }

    static String roman(int n) {
        int[] v = {1000, 900, 500, 400, 100, 90, 50, 40, 10, 9, 5, 4, 1};
        String[] s = {"M", "CM", "D", "CD", "C", "XC", "L", "XL", "X", "IX", "V", "IV", "I"};
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < v.length; i++) while (n >= v[i]) { n -= v[i]; sb.append(s[i]); }
        return sb.toString();
    }

    /**
     * Positions of labels that occur more than once (colour codes, case and spacing ignored): stock lines a
     * player could not tell apart by name.
     */
    public static java.util.Set<Integer> ambiguous(List<String> labels) {
        java.util.Map<String, List<Integer>> by = new java.util.HashMap<>();
        for (int i = 0; i < labels.size(); i++) {
            String l = labels.get(i) == null ? "" : labels.get(i).replaceAll("[&§][0-9a-fk-orA-FK-OR]", "")
                    .trim().replaceAll("\\s+", " ").toLowerCase(java.util.Locale.ROOT);
            by.computeIfAbsent(l, k -> new ArrayList<>()).add(i);
        }
        java.util.Set<Integer> out = new java.util.TreeSet<>();
        for (List<Integer> l : by.values()) if (l.size() > 1) out.addAll(l);
        return out;
    }

    /** Structural problems in the data, empty when it hangs together (used by a self-test and a unit test). */
    public static List<String> validate(List<Shop> shops) {
        List<String> bad = new ArrayList<>();
        java.util.Set<String> ids = new java.util.HashSet<>();
        java.util.Set<String> anchors = new java.util.HashSet<>();
        for (Shop s : shops) {
            if (s.id == null || !s.id.matches("[a-z0-9_]+")) bad.add("bad id " + s.id);
            if (!ids.add(s.id)) bad.add("duplicate shop " + s.id);
            if (s.name == null || s.name.isBlank()) bad.add(s.id + ": no name");
            if (s.island == null || s.anchor == null || !s.anchor.startsWith("npc.")) bad.add(s.id + ": bad island/anchor");
            else if (!anchors.add(s.island + "/" + s.anchor)) bad.add(s.id + ": anchor shared " + s.anchor);
            if (!"contract".equals(s.mode) && !"secondary".equals(s.mode)) bad.add(s.id + ": bad mode " + s.mode);
            if (!wellFormedReq(s.req)) bad.add(s.id + ": bad requirement '" + s.req + "'");
            if (s.entries == null || s.entries.isEmpty()) { bad.add(s.id + ": no stock"); continue; }
            for (Entry e : s.entries) {
                String where = s.id + "/" + e.item;
                if (e.item == null || e.item.isBlank()) bad.add(s.id + ": entry without item");
                if (e.amount < 1 || e.amount > 64) bad.add(where + ": amount " + e.amount);
                if (e.coins < 0 || e.bits < 0) bad.add(where + ": negative cost");
                if (!wellFormedReq(e.req)) bad.add(where + ": bad requirement '" + e.req + "'");
                if (e.coins == 0 && e.bits == 0 && !e.hasItemCosts() && !e.hasCurrency()) bad.add(where + ": free");
                if (e.items != null) for (ItemCost c : e.items) if (c.item == null || c.amount < 1) bad.add(where + ": bad item cost");
                if (e.currency != null) for (CurrencyCost c : e.currency) {
                    if (c.id == null || c.amount < 1) bad.add(where + ": bad currency cost");
                    if ("gem".equals(c.id)) bad.add(where + ": costs gems (pay-to-win currency)");
                }
                if (e.group != null && (s.groups == null || s.groups.isEmpty())) bad.add(where + ": group without groups");
                if (e.group != null && s.groups != null && !s.groups.isEmpty() && s.group(e.group) == null) bad.add(where + ": unknown group " + e.group);
            }
        }
        return bad;
    }
}
